using System.Collections;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SilencedEffect", menuName = "Data/Battle/Effects/Enemy/Silenced Effect")]
public class SilencedEffect : Effect
{
	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueStartOfTurnAction(SilenceCoroutine(effectAmount, effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	public IEnumerator SilenceCoroutine(int effectAmount, GameObject effectOwner)
	{
		yield return new WaitForSeconds(0.3f);
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		playerCurrentRunes.DisableAllRunes();
		yield return new WaitForSeconds(0.6f);
	}
}
